using System.Linq;using UnityEngine;using AntColony.Units;
public static class Animation1110Close {public static string Main(){var c=Object.FindObjectsByType<CommanderAnt>(FindObjectsInactive.Exclude).Where(x=>x.IsColonyMember).OrderBy(x=>Vector3.Distance(x.Position,Camera.main.transform.position)).First();var m=c.GetComponentInChildren<MeshyEquipmentGrip>().transform;var t=c.GetComponentsInChildren<Transform>().First(x=>x.name=="Socket.Tool.R");var cam=Camera.main;cam.orthographicSize=.3f;cam.transform.position=t.position+m.forward*.6f+m.right*.5f+Vector3.up*.15f;cam.transform.LookAt(t.position);return "grip closeup";}}
